INSERT INTO `news` (`id`, `title`, `summary`, `content`, `category`, `image_url`, `source_name`, `source_url`, `is_external`, `is_published`, `view_count`, `published_at`, `created_at`, `updated_at`, `is_featured`) VALUES
  (1, 'Công an thị xã Tân Châu ra quân cao điểm bảo đảm ANTT tuyến biên giới Vĩnh Xương', 'Lực lượng Công an thị xã phối hợp Đồn Biên phòng cửa khẩu quốc tế Vĩnh Xương tuần tra khép kín tuyến biên giới, phòng chống buôn lậu, xuất nhập cảnh trái phép và tội phạm ma tuý.', NULL, 'security', '/images/news/bien-gioi.jpg', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn', 1, 1, 0, '2026-07-09 00:00:00', '2026-08-25 04:40:05', '2026-08-25 14:25:25', 1),
  (2, 'Tuần tra đêm khép kín địa bàn các phường Long Thạnh, Long Châu, Long Phú', 'Tổ tuần tra 161 Công an thị xã Tân Châu duy trì tuần tra vũ trang ban đêm, kịp thời phát hiện, ngăn chặn các nhóm thanh thiếu niên tụ tập gây rối trật tự công cộng.', NULL, 'security', '/images/news/tuan-tra.jpg', 'Fanpage Công an TX Tân Châu', 'https://www.facebook.com/conganthixatanchauangiang', 1, 1, 0, '2026-07-07 00:00:00', '2026-07-10 04:40:05', '2026-08-31 08:27:17', 2),
  (3, 'Cảnh giác chiêu trò việc nhẹ lương cao dụ dỗ xuất cảnh trái phép sang Campuchia', 'Địa bàn biên giới Tân Châu là điểm nóng của thủ đoạn lôi kéo lao động vượt biên rồi cưỡng bức làm việc trong các cơ sở lừa đảo trực tuyến. Người dân tuyệt đối không tin lời mời chào trên mạng xã hội.', NULL, 'warning', '/images/news/lua-dao.jpg', 'bocongan.gov.vn', 'https://bocongan.gov.vn', 1, 1, 0, '2026-07-06 00:00:00', '2026-07-10 04:40:05', '2026-07-10 04:40:05', 0),
  (4, 'Giả danh công an gọi điện yêu cầu cài ứng dụng, chuyển tiền - thủ đoạn cũ, nạn nhân mới', 'Đối tượng mạo danh cán bộ điều tra đe doạ nạn nhân liên quan vụ án rồi yêu cầu chuyển tiền vào tài khoản tạm giữ. Công an không bao giờ làm việc qua điện thoại kèm yêu cầu chuyển tiền, đọc mã OTP.', NULL, 'warning', '/images/news/gia-danh.jpg', 'luatvietnam.vn', 'https://luatvietnam.vn', 1, 1, 0, '2026-07-04 00:00:00', '2026-07-10 04:40:05', '2026-07-10 04:40:05', 0),
  (5, 'Hướng dẫn đăng ký cư trú trực tuyến trên ứng dụng VNeID', 'Từng bước khai báo tạm trú, tạm vắng ngay trên điện thoại: chuẩn bị giấy tờ, điền tờ khai điện tử, theo dõi kết quả - không cần đến trụ sở công an.', NULL, 'guide', 'https://dichvucong.gov.vn/imgs/dvc-logo.png', 'dichvucong.gov.vn', 'https://dichvucong.gov.vn', 1, 1, 0, '2026-07-02 00:00:00', '2026-07-10 04:40:05', '2026-08-16 03:44:24', 1),
  (6, 'Công an Tân Châu cấp căn cước lưu động cho người già yếu, bệnh tật tại nhà', 'Tổ công tác mang thiết bị thu nhận sinh trắc học đến tận nhà phục vụ người cao tuổi, người khuyết tật trên địa bàn các phường, xã - bảo đảm không ai bị bỏ lại phía sau trong Đề án 06.', NULL, 'guide', '/images/news/can-cuoc.jpg', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn', 1, 1, 0, '2026-06-30 00:00:00', '2026-07-10 04:40:05', '2026-07-10 04:40:05', 0),
  (7, 'Nghị quyết 57-NQ/TW: đột phá phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia', 'Bộ Chính trị xác định khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số là đột phá quan trọng hàng đầu - nền tảng để hiện đại hoá quản trị quốc gia, trong đó có chuyển đổi số ngành Công an.', NULL, 'document', '/images/news/nq57.jpg', 'xaydungchinhsach.chinhphu.vn', 'https://xaydungchinhsach.chinhphu.vn', 1, 1, 0, '2026-06-28 00:00:00', '2026-07-10 04:40:05', '2026-07-10 04:40:05', 0),
  (8, 'Nghị quyết 66-NQ/TW về đổi mới công tác xây dựng và thi hành pháp luật trong kỷ nguyên mới', 'Hoàn thiện thể chế, đưa pháp luật đi vào cuộc sống - cơ sở chính trị quan trọng để các mô hình tiếp nhận ý kiến công dân như Hộp Thư An Ninh Số hoạt động minh bạch, đúng quy định.', NULL, 'document', '/images/news/nq66.jpg', 'vbpl.vn', 'https://vbpl.vn', 1, 1, 0, '2026-06-25 00:00:00', '2026-08-25 09:00:00', '2026-08-25 10:40:05', 0),
  (9, 'Công an thị xã Tân Châu ra quân cao điểm tấn công trấn áp tội phạm dịp cuối năm', 'Lực lượng Công an thị xã đồng loạt ra quân tuần tra vũ trang, kiểm soát các tuyến trọng điểm, tập trung trấn áp tội phạm trộm cắp, cướp giật và tệ nạn xã hội. Bà con phát hiện dấu hiệu nghi vấn có thể báo ngay qua Hộp Thư An Ninh Số hoặc số trực ban 113.', NULL, 'security', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn', 1, 1, 0, '2026-07-11 00:00:00', '2026-07-11 14:26:50', '2026-07-13 10:52:29', 0),
  (10, 'Nguyễn Anh Kiệt', 'Vào lúc 11h30 phút Kiệt đã dùng 1 cây dùi cui 20 cm tấn công nạn nhân nam trong tình trạng không còn mảnh vải che thân làm nạn nhân bị thương trong khách sạn.', NULL, 'security', 'https://www.shutterstock.com/image-photo/closeup-young-caucasian-man-holding-260nw-1244238916.jpg', 'Kietgay', 'https://ibb.co/LhQPys0h', 1, 1, 1, '2026-07-11 00:00:00', '2026-07-11 14:28:54', '2026-08-26 03:01:12', 0),
  (11, 'Kỷ niệm 80 năm Ngày truyền thống lực lượng An ninh nhân dân, đón nhận Huân chương Sao vàng', 'Ngày 11/7/2026, tại Hà Nội, Đảng ủy Công an Trung ương và Bộ Công an tổ chức Lễ kỷ niệm 80 năm Ngày truyền thống lực lượng An ninh nhân dân (12/7/1946 - 12/7/2026) và đón nhận Huân chương Sao vàng. Tổng Bí thư, Chủ tịch nước Tô Lâm đã đến dự và phát biểu chỉ đạo, ghi nhận những đóng góp to lớn của lực lượng trong sự nghiệp bảo vệ an ninh quốc gia.', NULL, 'security', 'https://bocongan.gov.vn/media/bca-media/bocongan-ctv/bocongan-ctv/large/photo-library-20260815194414-6a2d0c25-91e3-4851-a657-02f91edcae95-a04i4515.JPG', 'bocongan.gov.vn', 'https://bocongan.gov.vn', 1, 1, 0, '2026-07-11 00:00:00', '2026-07-13 10:33:28', '2026-08-16 06:23:00', 2),
  (12, 'Tội phạm về trật tự xã hội tại An Giang giảm gần 20% trong 6 tháng đầu năm 2026', 'Tại Hội nghị sơ kết công tác Công an 6 tháng đầu năm tổ chức ngày 4/7/2026, Công an tỉnh An Giang cho biết tội phạm về trật tự xã hội trên địa bàn đã được kéo giảm 19,74%. Lực lượng Công an tỉnh bảo đảm an toàn tuyệt đối cho 41 sự kiện chính trị, văn hóa quan trọng và 46 đoàn lãnh đạo cấp cao đến làm việc tại địa phương. Ba tập thể thuộc Công an tỉnh được trao Cờ thi đua của Chính phủ.', NULL, 'security', '/media/bg-nui-cam.webp', 'baophapluat.vn', 'https://baophapluat.vn', 1, 1, 0, '2026-07-04 00:00:00', '2026-07-13 10:33:28', '2026-08-16 06:20:41', 1),
  (13, 'An Giang triển khai bảo đảm an ninh, trật tự phục vụ APEC 2027 từ xa, từ sớm, từ cơ sở', 'Công an tỉnh An Giang đã triển khai kế hoạch bảo đảm an ninh, trật tự phục vụ Hội nghị cấp cao APEC 2027 tổ chức tại đặc khu Phú Quốc, với phương châm chủ động "từ xa, từ sớm và từ cơ sở". Đây là nhiệm vụ chính trị trọng tâm, đòi hỏi sự phối hợp chặt chẽ giữa lực lượng Công an với các cấp, các ngành và sự tham gia tích cực của quần chúng nhân dân.', NULL, 'security', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn', 1, 1, 0, '2026-07-08 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (14, 'Công an tỉnh An Giang ra mắt Câu lạc bộ "Niềm tin số tỉnh An Giang"', 'Công an tỉnh An Giang đã tổ chức gặp mặt các KOL, quản trị viên trang, hội, nhóm trên không gian mạng và ra mắt Câu lạc bộ "Niềm tin số tỉnh An Giang". Đây là mô hình nhằm phát huy vai trò của những người có ảnh hưởng trên mạng xã hội trong tuyên truyền chủ trương, chính sách, phản bác thông tin xấu độc và lan tỏa thông tin tích cực đến cộng đồng.', NULL, 'security', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn', 1, 1, 0, '2026-07-07 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (15, 'Cảnh giác tội phạm đánh bạc, cá độ trong thời gian diễn ra World Cup 2026', 'Công an tỉnh An Giang khuyến cáo bà con chủ động phòng ngừa các hành vi đánh bạc, cá độ bóng đá trong thời gian diễn ra World Cup 2026. Đây là thời điểm các đối tượng thường lợi dụng để tổ chức cá độ trên không gian mạng, kéo theo nguy cơ vỡ nợ, cho vay nặng lãi và các hệ lụy về an ninh trật tự. Bà con phát hiện dấu hiệu nghi vấn hãy báo ngay cho Công an nơi gần nhất.', NULL, 'warning', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn', 1, 1, 0, '2026-07-12 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (16, 'Cảnh báo thủ đoạn lừa đảo chiếm đoạt tài sản trên không gian mạng', 'Công an tỉnh An Giang đang tiến hành xác minh, tìm bị hại trong một vụ án lừa đảo chiếm đoạt tài sản. Các đối tượng thường giả danh cán bộ Công an, Viện Kiểm sát, nhân viên ngân hàng hoặc dụ dỗ đầu tư sinh lời cao để chiếm đoạt tiền. Bà con tuyệt đối KHÔNG cung cấp mã OTP, mật khẩu, thông tin căn cước cho người lạ; không chuyển tiền khi chưa xác minh rõ ràng.', NULL, 'warning', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn', 1, 1, 0, '2026-07-10 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (17, 'Tăng cường đấu tranh với tội phạm công nghệ cao và tội phạm ma túy', 'Lãnh đạo Công an tỉnh An Giang cho biết trong 6 tháng cuối năm 2026, lực lượng chức năng sẽ tiếp tục triển khai đồng bộ các giải pháp bảo đảm an ninh chính trị, trật tự an toàn xã hội; tăng cường đấu tranh phòng, chống các loại tội phạm, nhất là tội phạm sử dụng công nghệ cao, tội phạm ma túy và các hành vi vi phạm pháp luật trên không gian mạng.', NULL, 'warning', '/media/bg-nui-cam.webp', 'baophapluat.vn', 'https://baophapluat.vn', 1, 1, 0, '2026-07-09 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (18, 'Chiến dịch làm sạch dữ liệu, cấp căn cước và tài khoản định danh điện tử VNeID', 'Công an tỉnh An Giang phát động Chiến dịch rà soát, làm sạch, xây dựng dữ liệu dân cư; cấp căn cước và tài khoản định danh điện tử cho cá nhân, tổ chức; đồng thời triển khai Sổ sức khỏe điện tử trên ứng dụng VNeID. Bà con chưa có tài khoản định danh mức độ 2 hãy liên hệ Công an xã, phường nơi cư trú để được hướng dẫn kích hoạt.', NULL, 'guide', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn', 1, 1, 0, '2026-07-06 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (19, 'Bộ Công an tập huấn công tác số hóa hồ sơ, tài liệu về cư trú trên toàn quốc', 'Bộ Công an đã tổ chức tập huấn công tác số hóa hồ sơ, tài liệu về cư trú trên phạm vi toàn quốc. Việc số hóa giúp rút ngắn thời gian giải quyết thủ tục hành chính về cư trú, giảm giấy tờ bà con phải mang theo và tăng tính chính xác của dữ liệu dân cư quốc gia. Bà con có thể thực hiện nhiều thủ tục cư trú trực tuyến qua Cổng dịch vụ công.', NULL, 'guide', '/media/bg-nui-cam.webp', 'bocongan.gov.vn', 'https://bocongan.gov.vn', 1, 1, 0, '2026-07-05 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (20, 'Công an tỉnh An Giang đẩy mạnh cải cách thủ tục hành chính, phục vụ Nhân dân', 'Công an tỉnh An Giang tiếp tục tăng cường cải cách thủ tục hành chính, nâng cao chất lượng phục vụ Nhân dân, gắn với thực hiện hiệu quả Đề án 06 về phát triển ứng dụng dữ liệu dân cư, định danh và xác thực điện tử. Bà con được khuyến khích sử dụng dịch vụ công trực tuyến để tiết kiệm thời gian, chi phí đi lại.', NULL, 'guide', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn', 1, 1, 0, '2026-07-02 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (21, 'Nghị quyết số 10-NQ/TW của Bộ Chính trị về phát triển kinh tế có vốn đầu tư nước ngoài', 'Nghị quyết số 10-NQ/TW ngày 8/6/2026 của Bộ Chính trị về phát triển kinh tế có vốn đầu tư nước ngoài thể hiện sự chuyển đổi rõ nét trong tư duy thu hút và sử dụng nguồn vốn FDI: chuyển từ "thu hút dự án" sang "kiến tạo hệ sinh thái", lấy đổi mới sáng tạo, chuyển giao công nghệ và năng lực cạnh tranh quốc gia làm thước đo. Hội nghị toàn quốc quán triệt Nghị quyết đã được tổ chức trực tuyến đến các địa phương.', NULL, 'document', '/media/bg-nui-cam.webp', 'baoangiang.com.vn', 'https://baoangiang.com.vn', 1, 1, 0, '2026-07-03 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (22, 'Công điện số 47/CĐ-TTg về khắc phục hậu quả vụ tai nạn giao thông đường thủy tại Phú Quốc', 'Ngày 11/7/2026, Phó Thủ tướng Thường trực Chính phủ Phạm Gia Túc đã ký Công điện số 47/CĐ-TTg của Thủ tướng Chính phủ chỉ đạo khắc phục hậu quả vụ tai nạn giao thông đường thủy đặc biệt nghiêm trọng xảy ra trên địa bàn đặc khu Phú Quốc, tỉnh An Giang. Công điện yêu cầu tập trung cứu nạn, cứu hộ, hỗ trợ nạn nhân và tăng cường kiểm tra an toàn phương tiện thủy.', NULL, 'document', '/media/bg-nui-cam.webp', 'bocongan.gov.vn', 'https://bocongan.gov.vn', 1, 1, 0, '2026-07-11 00:00:00', '2026-07-13 10:33:28', '2026-07-13 10:52:29', 0),
  (23, 'Tội phạm về trật tự xã hội tại An Giang giảm gần 20% trong 6 tháng đầu năm 2026', 'Tại Hội nghị sơ kết công tác Công an ngày 4/7/2026, Công an tỉnh An Giang cho biết tội phạm về trật tự xã hội trên địa bàn được kéo giảm 19,74%. Lực lượng đã bảo đảm an toàn tuyệt đối cho 41 sự kiện chính trị, văn hóa quan trọng và 46 đoàn lãnh đạo cấp cao đến làm việc. Ba tập thể thuộc Công an tỉnh được trao Cờ thi đua của Chính phủ.', NULL, 'security', '/media/bg-nui-sam.webp', 'baophapluat.vn', 'https://baophapluat.vn/toi-pham-ve-trat-tu-xa-hoi-tai-an-giang-giam-gan-20-trong-6-thang-dau-nam-2026.html', 1, 1, 0, '2026-07-04 00:00:00', '2026-07-13 10:44:01', '2026-07-13 10:44:01', 0),
  (24, 'Cục An ninh điều tra Bộ Công an kiểm tra công tác tại Công an tỉnh An Giang', 'Ngày 17-18/6/2026, Cục An ninh điều tra Bộ Công an tổ chức kiểm tra công tác An ninh điều tra 6 tháng đầu năm tại Phòng An ninh điều tra Công an tỉnh An Giang. Lực lượng An ninh điều tra đã nắm chắc, dự báo sát tình hình, chủ động tham mưu nhiều chủ trương, giải pháp trong điều tra, xử lý tội phạm, góp phần bảo đảm an ninh trật tự trên địa bàn tỉnh.', NULL, 'security', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/cuc-an-ninh-dieu-tra-bo-cong-an-kiem-tra-cong-tac-an-ninh-dieu-tra-06-thang-dau-nam-2026-tai-phong-an-ninh-dieu-tra-cong-an-tinh-an-giang', 1, 1, 0, '2026-06-18 00:00:00', '2026-07-13 10:44:01', '2026-07-13 10:44:01', 0),
  (25, 'Công an tỉnh An Giang sơ kết công tác chính trị 6 tháng đầu năm 2026', 'Ngày 9/7/2026, Phòng Công tác chính trị Công an tỉnh An Giang tổ chức Hội nghị sơ kết 6 tháng đầu năm. Đơn vị đã triển khai phong trào thi đua "Ba nhất: Kỷ luật nhất - Trung thành nhất - Gần dân nhất"; thực hiện 24 chuyên mục "Vì an ninh Tổ quốc" với 185 tin, bài phát sóng và gần 850 tin, bài đăng trên các nền tảng truyền thông của lực lượng.', NULL, 'security', '/media/bg-ho-tinh-tam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/phong-cong-tac-chinh-tri-cong-an-tinh-an-giang-so-ket-cong-tac-6-thang-dau-nam-2026', 1, 1, 0, '2026-07-09 00:00:00', '2026-07-13 10:44:01', '2026-07-13 10:44:01', 0),
  (26, 'An Giang tập trung tăng trưởng kinh tế, ứng phó thiên tai và bảo đảm an ninh trật tự', 'Trong 6 tháng đầu năm 2026, GRDP của An Giang ước tăng 8,83%, đứng đầu khu vực Đồng bằng sông Cửu Long. Về an ninh trật tự, lãnh đạo Công an tỉnh cho biết sẽ tiếp tục tăng cường đấu tranh phòng, chống các loại tội phạm, nhất là tội phạm sử dụng công nghệ cao, tội phạm ma túy và các hành vi vi phạm pháp luật trên không gian mạng.', NULL, 'security', '/media/bg-lang-noi.webp', 'baophapluat.vn', 'https://baophapluat.vn/an-giang-tap-trung-tang-truong-kinh-te-ung-pho-thien-tai-va-bao-ton-di-san-oc-eo.html', 1, 1, 0, '2026-07-08 00:00:00', '2026-07-13 10:44:01', '2026-07-13 10:44:01', 0),
  (27, 'Phòng, chống tội phạm đánh bạc, cá độ bóng đá mùa World Cup 2026', 'World Cup 2026 diễn ra từ 11/6 đến 19/7/2026. Lợi dụng sức nóng mùa giải, các đối tượng lập website, ứng dụng cá độ có máy chủ đặt ở nước ngoài để lôi kéo người dân. Công an An Giang cảnh báo: cá độ bóng đá ăn tiền là hành vi đánh bạc, có thể bị phạt tù tới 7 năm (Điều 321) hoặc 10 năm nếu tổ chức đánh bạc (Điều 322 Bộ luật Hình sự). Bà con phát hiện dấu hiệu hãy tố giác ngay.', NULL, 'warning', 'https://congan.angiang.gov.vn/sites/default/files/inline-images/image_118.png', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/phong-chong-toi-pham-lien-quan-den-danh-bac-ca-do-bong-da-mua-world-cup-2026', 1, 1, 0, '2026-07-12 00:00:00', '2026-07-13 10:44:01', '2026-07-25 03:23:13', 0),
  (28, 'Công an phường Long Phú ứng dụng trí tuệ nhân tạo AI để tuyên truyền phòng ngừa đánh bạc', 'Công an phường Long Phú đã đổi mới công tác tuyên truyền bằng cách ứng dụng trí tuệ nhân tạo (AI) tạo video, infographic và phim ngắn sinh động, dễ hiểu, đăng tải trên Facebook, Zalo OA và phát tại các cuộc họp dân. Qua đó giúp bà con nhận diện rõ thủ đoạn tổ chức đánh bạc, cá độ bóng đá trên không gian mạng trong mùa World Cup 2026.', NULL, 'warning', '/media/bg-ho-tinh-tam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/cong-an-phuong-long-phu-day-manh-tuyen-tuyen-phong-ngua-toi-pham-danh-bac-trong-mua-world-cup-2026-bang-ung-dung-tri-tue-nhan-tao-ai', 1, 1, 0, '2026-07-10 00:00:00', '2026-07-13 10:44:01', '2026-07-13 10:44:01', 0),
  (29, 'Cảnh giác thủ đoạn dụ dỗ cá độ trực tuyến: "chơi thử miễn phí", "cam kết lợi nhuận"', 'Công an xã An Châu cảnh báo các đối tượng thường quảng cáo trên mạng xã hội, trang tin thể thao và hội nhóm trực tuyến với những lời mời gọi như "chơi thử miễn phí", "tỷ lệ thắng cao", "cam kết lợi nhuận", "rút tiền nhanh" để dụ người chơi nạp tiền cá cược. Bà con tuyệt đối không truy cập, đăng ký tài khoản hoặc chia sẻ các đường link, hội nhóm có dấu hiệu tổ chức cá độ trái phép.', NULL, 'warning', '/media/bg-nui-sam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/cong-an-xa-an-chau-khuyen-cao-nguoi-dan-khong-tham-gia-ca-do-bong-da-mua-world-cup-2026', 1, 1, 0, '2026-07-06 00:00:00', '2026-07-13 10:44:01', '2026-07-13 10:44:01', 0),
  (30, 'Chiến dịch làm sạch dữ liệu, cấp căn cước và tài khoản định danh điện tử VNeID', 'Chiến dịch rà soát, làm sạch, xây dựng dữ liệu; cấp căn cước, tài khoản định danh điện tử; Sổ sức khỏe điện tử trên VNeID được triển khai trên địa bàn tỉnh An Giang. Chiến dịch nhằm tạo điều kiện để bà con thực hiện các giao dịch, thủ tục hành chính mọi lúc, mọi nơi trên nền tảng định danh và xác thực điện tử.', NULL, 'guide', '/media/bg-lang-noi.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/phat-dong-trien-khai-chien-dich-ra-soat-lam-sach-du-lieu-cap-can-cuoc-tai-khoan-dinh-danh-dien-tu', 1, 1, 0, '2026-06-28 00:00:00', '2026-07-13 10:44:01', '2026-07-13 10:44:01', 0),
  (31, 'Chỉ tiêu cụ thể của Chiến dịch: 100% công dân từ 6 tuổi được cấp thẻ Căn cước', 'Chiến dịch triển khai từ 20/6/2026 đến 15/9/2026 với các chỉ tiêu: 100% công dân từ đủ 6 tuổi trở lên được cấp thẻ Căn cước; 95% người từ 14 tuổi trở lên có tài khoản định danh điện tử mức 2; 90% công dân có thẻ BHYT được tích hợp Sổ sức khỏe điện tử trên VNeID, hướng tới thay thế sổ khám bệnh bằng giấy.', NULL, 'guide', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/xa-son-kien-phat-dong-chien-dich-ra-soat-lam-sach-xay-dung-du-lieu-cap-can-cuoc-tai-khoan-dinh-danh-dien-tu', 1, 1, 0, '2026-06-23 00:00:00', '2026-07-13 10:44:01', '2026-07-13 10:44:01', 0),
  (32, 'Hướng dẫn tích hợp Sổ sức khỏe điện tử trên ứng dụng VNeID', 'Công an các xã, phường phối hợp ngành Y tế hướng dẫn bà con tích hợp và sử dụng Sổ sức khỏe điện tử trên ứng dụng VNeID, từng bước hình thành hồ sơ sức khỏe điện tử, tạo thuận lợi trong khám chữa bệnh. Bà con chưa có tài khoản định danh mức 2 hãy liên hệ Công an nơi cư trú để được hỗ trợ đăng ký, kích hoạt.', NULL, 'guide', '/media/bg-ho-tinh-tam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/hoa-hung-phat-dong-chien-dich-lam-sach-du-lieu-cap-can-cuoc-va-dinh-danh-dien-tu', 1, 1, 0, '2026-06-22 00:00:00', '2026-07-13 10:44:01', '2026-07-13 10:44:01', 0),
  (33, 'Nghị quyết 10-NQ/TW của Bộ Chính trị về phát triển kinh tế có vốn đầu tư nước ngoài', 'Ngày 8/6/2026, Tổng Bí thư, Chủ tịch nước Tô Lâm thay mặt Bộ Chính trị ký ban hành Nghị quyết số 10-NQ/TW về phát triển kinh tế có vốn đầu tư nước ngoài. Nghị quyết thể hiện sự thay đổi trong tư duy phát triển: chuyển từ thu hút đầu tư sang phát triển kinh tế có vốn đầu tư nước ngoài, từ coi trọng quy mô vốn sang coi trọng chất lượng, hiệu quả và giá trị gia tăng.', NULL, 'document', 'https://cdn.thuvienphapluat.vn/phap-luat/2022-2/TTKP/nghi-quyet-10-2026.jpg', 'vietnamplus.vn', 'https://www.vietnamplus.vn/nghi-quyet-10-nqtw-the-hien-su-thay-doi-trong-tu-duy-phat-trien-post1121402.vnp', 1, 1, 0, '2026-06-30 00:00:00', '2026-07-13 10:44:01', '2026-08-16 03:40:32', 1),
  (34, 'Toàn văn Nghị quyết 10-NQ/TW: mục tiêu đến năm 2045 đóng góp 30% GDP', 'Nghị quyết 10-NQ/TW xác định 6 quan điểm chỉ đạo và 8 chính sách quan trọng. Mục tiêu đến năm 2045, khu vực kinh tế có vốn đầu tư nước ngoài chiếm khoảng 25% tổng vốn đầu tư toàn xã hội và đóng góp khoảng 30% GDP. Nghị quyết ưu tiên thu hút đầu tư vào chip bán dẫn, trí tuệ nhân tạo, dữ liệu lớn, công nghệ sinh học và công nghiệp xanh.', NULL, 'document', '/media/bg-lang-noi.webp', 'thuvienphapluat.vn', 'https://thuvienphapluat.vn/phap-luat/ho-tro-phap-luat/toan-van-nghi-quyet-10nqtw-phat-trien-kinh-te-co-von-dau-tu-nuoc-ngoai-ngay-862026-ra-sao-274324.html', 1, 1, 0, '2026-06-29 00:00:00', '2026-07-13 10:44:01', '2026-08-16 06:20:42', 1),
  (35, 'Tội phạm về trật tự xã hội tại An Giang giảm gần 20% trong 6 tháng đầu năm 2026', 'Tại Hội nghị sơ kết công tác Công an ngày 4/7/2026, Công an tỉnh An Giang cho biết tội phạm về trật tự xã hội trên địa bàn được kéo giảm 19,74%. Lực lượng đã bảo đảm an toàn tuyệt đối cho 41 sự kiện chính trị, văn hóa quan trọng và 46 đoàn lãnh đạo cấp cao đến làm việc. Ba tập thể thuộc Công an tỉnh được trao Cờ thi đua của Chính phủ.', NULL, 'security', '/media/bg-nui-sam.webp', 'baophapluat.vn', 'https://baophapluat.vn/toi-pham-ve-trat-tu-xa-hoi-tai-an-giang-giam-gan-20-trong-6-thang-dau-nam-2026.html', 1, 1, 0, '2026-07-04 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (36, 'Cục An ninh điều tra Bộ Công an kiểm tra công tác tại Công an tỉnh An Giang', 'Ngày 17-18/6/2026, Cục An ninh điều tra Bộ Công an tổ chức kiểm tra công tác An ninh điều tra 6 tháng đầu năm tại Phòng An ninh điều tra Công an tỉnh An Giang. Lực lượng An ninh điều tra đã nắm chắc, dự báo sát tình hình, chủ động tham mưu nhiều chủ trương, giải pháp trong điều tra, xử lý tội phạm, góp phần bảo đảm an ninh trật tự trên địa bàn tỉnh.', NULL, 'security', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/cuc-an-ninh-dieu-tra-bo-cong-an-kiem-tra-cong-tac-an-ninh-dieu-tra-06-thang-dau-nam-2026-tai-phong-an-ninh-dieu-tra-cong-an-tinh-an-giang', 1, 1, 0, '2026-06-18 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (37, 'Công an tỉnh An Giang sơ kết công tác chính trị 6 tháng đầu năm 2026', 'Ngày 9/7/2026, Phòng Công tác chính trị Công an tỉnh An Giang tổ chức Hội nghị sơ kết 6 tháng đầu năm. Đơn vị đã triển khai phong trào thi đua "Ba nhất: Kỷ luật nhất - Trung thành nhất - Gần dân nhất"; thực hiện 24 chuyên mục "Vì an ninh Tổ quốc" với 185 tin, bài phát sóng và gần 850 tin, bài đăng trên các nền tảng truyền thông của lực lượng.', NULL, 'security', '/media/bg-ho-tinh-tam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/phong-cong-tac-chinh-tri-cong-an-tinh-an-giang-so-ket-cong-tac-6-thang-dau-nam-2026', 1, 1, 0, '2026-07-09 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (38, 'An Giang tập trung tăng trưởng kinh tế, ứng phó thiên tai và bảo đảm an ninh trật tự', 'Trong 6 tháng đầu năm 2026, GRDP của An Giang ước tăng 8,83%, đứng đầu khu vực Đồng bằng sông Cửu Long. Về an ninh trật tự, lãnh đạo Công an tỉnh cho biết sẽ tiếp tục tăng cường đấu tranh phòng, chống các loại tội phạm, nhất là tội phạm sử dụng công nghệ cao, tội phạm ma túy và các hành vi vi phạm pháp luật trên không gian mạng.', NULL, 'security', '/media/bg-lang-noi.webp', 'baophapluat.vn', 'https://baophapluat.vn/an-giang-tap-trung-tang-truong-kinh-te-ung-pho-thien-tai-va-bao-ton-di-san-oc-eo.html', 1, 1, 0, '2026-07-08 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (39, 'Phòng, chống tội phạm đánh bạc, cá độ bóng đá mùa World Cup 2026', 'World Cup 2026 diễn ra từ 11/6 đến 19/7/2026. Lợi dụng sức nóng mùa giải, các đối tượng lập website, ứng dụng cá độ có máy chủ đặt ở nước ngoài để lôi kéo người dân. Công an An Giang cảnh báo: cá độ bóng đá ăn tiền là hành vi đánh bạc, có thể bị phạt tù tới 7 năm (Điều 321) hoặc 10 năm nếu tổ chức đánh bạc (Điều 322 Bộ luật Hình sự). Bà con phát hiện dấu hiệu hãy tố giác ngay.', NULL, 'warning', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/phong-chong-toi-pham-lien-quan-den-danh-bac-ca-do-bong-da-mua-world-cup-2026', 1, 1, 0, '2026-07-12 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (40, 'Công an phường Long Phú ứng dụng trí tuệ nhân tạo AI để tuyên truyền phòng ngừa đánh bạc', 'Công an phường Long Phú đã đổi mới công tác tuyên truyền bằng cách ứng dụng trí tuệ nhân tạo (AI) tạo video, infographic và phim ngắn sinh động, dễ hiểu, đăng tải trên Facebook, Zalo OA và phát tại các cuộc họp dân. Qua đó giúp bà con nhận diện rõ thủ đoạn tổ chức đánh bạc, cá độ bóng đá trên không gian mạng trong mùa World Cup 2026.', NULL, 'warning', '/media/bg-ho-tinh-tam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/cong-an-phuong-long-phu-day-manh-tuyen-tuyen-phong-ngua-toi-pham-danh-bac-trong-mua-world-cup-2026-bang-ung-dung-tri-tue-nhan-tao-ai', 1, 1, 0, '2026-07-10 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (41, 'Cảnh giác thủ đoạn dụ dỗ cá độ trực tuyến: "chơi thử miễn phí", "cam kết lợi nhuận"', 'Công an xã An Châu cảnh báo các đối tượng thường quảng cáo trên mạng xã hội, trang tin thể thao và hội nhóm trực tuyến với những lời mời gọi như "chơi thử miễn phí", "tỷ lệ thắng cao", "cam kết lợi nhuận", "rút tiền nhanh" để dụ người chơi nạp tiền cá cược. Bà con tuyệt đối không truy cập, đăng ký tài khoản hoặc chia sẻ các đường link, hội nhóm có dấu hiệu tổ chức cá độ trái phép.', NULL, 'warning', '/media/bg-nui-sam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/cong-an-xa-an-chau-khuyen-cao-nguoi-dan-khong-tham-gia-ca-do-bong-da-mua-world-cup-2026', 1, 1, 0, '2026-07-06 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (42, 'Chiến dịch làm sạch dữ liệu, cấp căn cước và tài khoản định danh điện tử VNeID', 'Chiến dịch rà soát, làm sạch, xây dựng dữ liệu; cấp căn cước, tài khoản định danh điện tử; Sổ sức khỏe điện tử trên VNeID được triển khai trên địa bàn tỉnh An Giang. Chiến dịch nhằm tạo điều kiện để bà con thực hiện các giao dịch, thủ tục hành chính mọi lúc, mọi nơi trên nền tảng định danh và xác thực điện tử.', NULL, 'guide', '/media/bg-lang-noi.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/phat-dong-trien-khai-chien-dich-ra-soat-lam-sach-du-lieu-cap-can-cuoc-tai-khoan-dinh-danh-dien-tu', 1, 1, 0, '2026-06-28 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (43, 'Chỉ tiêu cụ thể của Chiến dịch: 100% công dân từ 6 tuổi được cấp thẻ Căn cước', 'Chiến dịch triển khai từ 20/6/2026 đến 15/9/2026 với các chỉ tiêu: 100% công dân từ đủ 6 tuổi trở lên được cấp thẻ Căn cước; 95% người từ 14 tuổi trở lên có tài khoản định danh điện tử mức 2; 90% công dân có thẻ BHYT được tích hợp Sổ sức khỏe điện tử trên VNeID, hướng tới thay thế sổ khám bệnh bằng giấy.', NULL, 'guide', '/media/bg-nui-cam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/xa-son-kien-phat-dong-chien-dich-ra-soat-lam-sach-xay-dung-du-lieu-cap-can-cuoc-tai-khoan-dinh-danh-dien-tu', 1, 1, 0, '2026-06-23 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (44, 'Hướng dẫn tích hợp Sổ sức khỏe điện tử trên ứng dụng VNeID', 'Công an các xã, phường phối hợp ngành Y tế hướng dẫn bà con tích hợp và sử dụng Sổ sức khỏe điện tử trên ứng dụng VNeID, từng bước hình thành hồ sơ sức khỏe điện tử, tạo thuận lợi trong khám chữa bệnh. Bà con chưa có tài khoản định danh mức 2 hãy liên hệ Công an nơi cư trú để được hỗ trợ đăng ký, kích hoạt.', NULL, 'guide', '/media/bg-ho-tinh-tam.webp', 'congan.angiang.gov.vn', 'https://congan.angiang.gov.vn/hoa-hung-phat-dong-chien-dich-lam-sach-du-lieu-cap-can-cuoc-va-dinh-danh-dien-tu', 1, 1, 0, '2026-06-22 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (45, 'Nghị quyết 10-NQ/TW của Bộ Chính trị về phát triển kinh tế có vốn đầu tư nước ngoài', 'Ngày 8/6/2026, Tổng Bí thư, Chủ tịch nước Tô Lâm thay mặt Bộ Chính trị ký ban hành Nghị quyết số 10-NQ/TW về phát triển kinh tế có vốn đầu tư nước ngoài. Nghị quyết thể hiện sự thay đổi trong tư duy phát triển: chuyển từ thu hút đầu tư sang phát triển kinh tế có vốn đầu tư nước ngoài, từ coi trọng quy mô vốn sang coi trọng chất lượng, hiệu quả và giá trị gia tăng.', NULL, 'document', '/media/bg-nui-sam.webp', 'vietnamplus.vn', 'https://www.vietnamplus.vn/nghi-quyet-10-nqtw-the-hien-su-thay-doi-trong-tu-duy-phat-trien-post1121402.vnp', 1, 1, 0, '2026-06-30 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (46, 'Toàn văn Nghị quyết 10-NQ/TW: mục tiêu đến năm 2045 đóng góp 30% GDP', 'Nghị quyết 10-NQ/TW xác định 6 quan điểm chỉ đạo và 8 chính sách quan trọng. Mục tiêu đến năm 2045, khu vực kinh tế có vốn đầu tư nước ngoài chiếm khoảng 25% tổng vốn đầu tư toàn xã hội và đóng góp khoảng 30% GDP. Nghị quyết ưu tiên thu hút đầu tư vào chip bán dẫn, trí tuệ nhân tạo, dữ liệu lớn, công nghệ sinh học và công nghiệp xanh.', NULL, 'document', '/media/bg-lang-noi.webp', 'thuvienphapluat.vn', 'https://thuvienphapluat.vn/phap-luat/ho-tro-phap-luat/toan-van-nghi-quyet-10nqtw-phat-trien-kinh-te-co-von-dau-tu-nuoc-ngoai-ngay-862026-ra-sao-274324.html', 1, 1, 0, '2026-06-29 00:00:00', '2026-07-13 10:52:28', '2026-07-13 10:52:28', 0),
  (47, 'Cảnh báo: kẻ gian chiếm tài khoản Zalo, Facebook rồi giả danh chính chủ hỏi vay tiền', 'Công an xã Khánh Hưng (tỉnh Cà Mau) cảnh báo một thủ đoạn đang lan rộng: thay vì dựng kịch bản lừa phức tạp, kẻ gian tìm cách chiếm quyền điều khiển tài khoản Zalo, Facebook, Telegram của người dân. Khi đã kiểm soát được tài khoản, chúng đóng vai chính chủ nhắn cho người thân, bạn bè trong danh bạ, viện lý do gấp gáp để hỏi vay hoặc nhờ chuyển tiền. Vì tin nhắn đến từ đúng tài khoản người quen nên nhiều người mất cảnh giác. Bà con lưu ý: nhận được tin nhắn hỏi vay tiền, dù từ tài khoản người thân, hãy gọi điện thoại trực tiếp xác minh trước khi chuyển bất kỳ khoản nào.', NULL, 'warning', '/media/bg-lang-noi.webp', 'cafef.vn', 'https://cafef.vn/cong-an-thong-bao-toi-tat-ca-nhung-ai-nhan-tin-nhan-zalo-messenger-co-noi-dung-sau-18826082406055387.chn', 1, 1, 1, '2026-08-25 00:00:00', '2026-08-25 14:37:08', '2026-08-25 14:37:41', 0),
  (48, 'Cảnh giác thủ đoạn gửi "Giấy mời" giả mạo cơ quan nhà nước về thủ tục đất đai', 'Xuất hiện thủ đoạn lừa đảo mới liên quan tới thủ tục đất đai: kẻ gian tự làm giả "Giấy mời" mang danh Ủy ban nhân dân hoặc cơ quan quản lý đất đai, rồi mang trực tiếp tới nhà người dân hoặc phát tán qua tin nhắn Zalo, Facebook. Mục đích là tạo lòng tin để dẫn dụ người dân làm theo hướng dẫn, cung cấp thông tin cá nhân hoặc chuyển tiền. Bà con nhận được giấy mời hoặc tin nhắn kiểu này nên mang tới trụ sở công an, ủy ban xã để xác minh, tuyệt đối không làm theo hướng dẫn qua điện thoại hay mạng xã hội.', NULL, 'warning', '/media/bg-nui-cam.webp', 'cafebiz.vn', 'https://cafebiz.vn/cong-an-canh-bao-chieu-thuc-lua-dao-moi-lien-quan-thu-tuc-dat-dai-176260812185256904.chn', 1, 1, 0, '2026-08-22 00:00:00', '2026-08-25 14:37:08', '2026-08-25 14:37:08', 0);
