  (70, 'GNH35B', 'tiếp tục làm và chỉnh sửa về gửi ý kiến khi đến bước cuối cùng mà gửi ẩn danh nó báo chưa đủ thông tin phải quay lại thì rất phiền nên hãy đặt nút quay lại từ đầu ngay tại đó và khi chưa xác minh chống bot thì chưa cho qua,tin tức xếp tối đa 21 bảng tin mỗi mục ở dưới muốn xem tất cả thì bấm xem thêm đặt nút ở dưới bên phải', 'Phản ánh, kiến nghị về: "tiếp tục làm và chỉnh sửa về gửi ý kiến khi đến bước cuối cùng mà gửi ẩn danh nó báo chưa đủ thông tin phải quay lại thì rất phiền nên hãy đặt nút quay lại từ đầu ngay tại đó và khi chưa xác minh chống bot thì chưa cho qua,tin tức xếp tối đa 21 bảng tin mỗi mục ở dưới muốn xem tất cả thì bấm xem thêm đặt nút ở dưới bên phải"', NULL, NULL, '6527a56060638b006176c9609a31e3990b8d7017631bc5cfc65b3be49f7c18b3', 1, 1, NULL, NULL, NULL, 'pending_review', NULL, NULL, NULL, NULL, NULL, 0, NULL, 'd96db4c365622dc725597bf05f267492', NULL, '2026-08-18 08:42:53', '2026-08-18 08:42:53', NULL, '2026-09-07 08:42:53', NULL, 0, 1, NULL, NULL, 'normal', 'thuong', NULL, NULL, 0, NULL, NULL, '$2b$10$FGhmFMx4rwpATs7UkgAp1.8OciIU4Fufksb9Ia3BWmRCH7L3MoYwe', '1877431e-fedb-475c-907c-e0994db5bf2c', 0),
  (71, '9ZPWAK', 'Kính gửi Ban quản lý khu vực / Cán bộ phụ trách địa bàn,\n\nTôi xin bổ sung thông tin chi tiết về sự việc tôi đã báo cáo như sau:\n\nThời gian xảy ra: Tình trạng này diễn ra liên tục, nghiêm trọng nhất là từ 22h00 đến 01h00 sáng các ngày cuối tuần (thứ 7 và Chủ nhật vừa qua).\n\nĐịa điểm: Tại bãi đất trống đối diện nhà số 45, đường Trần Hưng Đạo, Khóm 2.\n\nNgười liên quan: Quán ăn đêm "Hải Sản Vui Vẻ" gần đó và một nhóm khách hàng thường xuyên tụ tập.\n\nMô tả cụ thể: Quán ăn thường xuyên cho khách ngồi lấn chiếm lối đi chung, hát karaoke bằng loa kéo với âm lượng rất lớn qua', 'Phản ánh, kiến nghị về: "Kính gửi Ban quản lý khu vực / Cán bộ phụ trách địa bàn, Tôi xin bổ sung thông tin chi tiết về sự việc tôi đã báo cáo như sau: Thời gian xảy ra: Tình trạng này diễn ra liên tục, nghiêm trọng nhất là từ 22h00 đến 01h00 sáng các ngày cuối tuần (thứ 7 và Chủ nhật vừa qua). Địa điểm: Tại bãi đất trống đối diện nhà số 45, đường Trần Hưng Đạo, Khóm 2. Người liên quan: Quán ăn đêm "Hải Sản Vui Vẻ" gần đó và một nhóm khách hàng thường xuyên tụ tập. Mô tả cụ thể: Quán ăn thường xuyên cho khách ngồi lấn chiếm lối đi chung, hát karaoke bằng loa kéo với âm lượng rất lớn qua"', NULL, NULL, '8399119b348d47f154ad9b1119bf71e2eb7466f9326e6caa5e24b7a27441b7ab', 3, 3, 'enc:v1:37eebd1fcafe1dac05e802ff:95b2b57795879ff4327eaa15d8e0e7a3:545bace3b3', 'enc:v1:88b7b0ef7238990b1ac796eb:43a1c22f296f0597a5444a5622ff4d92:95f615e27191c62caf4f', NULL, 'spam', 'Cán bộ đánh dấu tin rác', NULL, NULL, NULL, NULL, 0, NULL, 'd96db4c365622dc725597bf05f267492', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', '2026-08-22 13:13:25', '2026-08-22 14:56:32', '67a0dc89744fe1d99918f56b37c2d204fb455b4656ccd00ce0692b88dfd344b0', '2026-09-06 13:13:24', NULL, 1, 0, NULL, NULL, 'important', 'thuong', '2026-08-22 14:56:32', 1, 0, NULL, NULL, '$2b$10$6Wq6XjBSSQCTRrJANdv8Ku5ROogMIUwbFBvkcnBGNbc/CM8mwjss2', 'f6e1b408-9013-4090-adba-b448dcc95ff2', 1),
  (72, '2PFQZ8', '"Vào khoảng 20 giờ 15 phút tối qua, tại khu vực trước nhà số 45 đường Lê Lợi, Khóm 3 (gần tiệm tạp hóa Cô Ba), tôi phát hiện 2 thanh niên đi xe Wave màu xanh đen có biểu hiện nghi vấn. Biển số xe bị dán băng keo che mờ, chỉ thấy đoạn đầu 68-B1. Cả hai mặc áo khoác đen, đội nón bảo hiểm đỏ, liên tục lảng vảng áp sát người đi đường. Sau đó họ giật túi xách của một phụ nữ rồi chạy tẩu thoát về hướng cầu vượt. Nhờ lực lượng chức năng trích xuất camera khu vực này để kiểm tra xử lý."', 'Phản ánh, kiến nghị về: ""Vào khoảng 20 giờ 15 phút tối qua, tại khu vực trước nhà số 45 đường Lê Lợi, Khóm 3 (gần tiệm tạp hóa Cô Ba), tôi phát hiện 2 thanh niên đi xe Wave màu xanh đen có biểu hiện nghi vấn. Biển số xe bị dán băng keo che mờ, chỉ thấy đoạn đầu 68-B1. Cả hai mặc áo khoác đen, đội nón bảo hiểm đỏ, liên tục lảng vảng áp sát người đi đường. Sau đó họ giật túi xách của một phụ nữ rồi chạy tẩu thoát về hướng cầu vượt. Nhờ lực lượng chức năng trích xuất camera khu vực này để kiểm tra xử lý.""', NULL, NULL, 'd94d5d2d261a4d7bbc8fb204e3db8d3d5871a40990977203788946749123e9c5', 3, 3, 'enc:v1:c0dec442887c9a6fad6ee5a3:19e0b6ffe8f1699f0dea650c05f44226:1a5415134e', 'enc:v1:675690430e6c3e3488746a2f:3e5dc65fc5e282fc466c46022ef33572:1584bb2944f2a9e6d469', NULL, 'received', 'Dọn theo lô cùng thiết bị với hồ sơ Q5YCQP', NULL, NULL, NULL, NULL, 0, NULL, 'd96db4c365622dc725597bf05f267492', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', '2026-08-22 14:36:39', '2026-08-24 12:43:12', 'd1205690de3d0d2a037017f19e59465aa5dd5d2de4e10e7b6e9a4912bb21abd1', '2026-09-06 14:36:39', 12, 1, 0, NULL, NULL, 'urgent', 'thuong', NULL, NULL, 0, NULL, NULL, '$2b$10$mxhuUiz7L4g2MvKfd75LdOsgRmbaolf8B031GzdiVi8nQQm73vTwG', '25ca2ec1-956f-4e57-b70d-2e263ea23eef', 1),
  (73, 'Q5YCQP', 'Khoảng 14 giờ 30 phút chiều nay, tại hẻm 12 đường Trần Hưng Đạo, Ấp 2 (đối diện tiệm sửa xe Minh), tôi thấy 1 người đàn ông khoảng 35 tuổi, cao tầm 1m70, da ngăm, có xăm hình ở cánh tay phải. Người này đi xe Sirius màu xám, biển số 65-E1 882.xx, lảng vảng trước nhà số 12/4 đang khóa cửa. Sau đó hắn dùng kềm cắt khóa cổng, dắt chiếc xe SH màu trắng ra ngoài rồi phóng vọt về hướng Quốc lộ. Nhờ công an kiểm tra trích xuất camera khu vực này."', 'Phản ánh, kiến nghị về: "Khoảng 14 giờ 30 phút chiều nay, tại hẻm 12 đường Trần Hưng Đạo, Ấp 2 (đối diện tiệm sửa xe Minh), tôi thấy 1 người đàn ông khoảng 35 tuổi, cao tầm 1m70, da ngăm, có xăm hình ở cánh tay phải. Người này đi xe Sirius màu xám, biển số 65-E1 882.xx, lảng vảng trước nhà số 12/4 đang khóa cửa. Sau đó hắn dùng kềm cắt khóa cổng, dắt chiếc xe SH màu trắng ra ngoài rồi phóng vọt về hướng Quốc lộ. Nhờ công an kiểm tra trích xuất camera khu vực này.""', NULL, NULL, 'b44d40c1585094c43e1db6076cd86cd3f0e4839c09ded3bf135f8114a77bc9b2', 3, 3, 'enc:v1:703e45731c821acc9911b9b1:4e0b02401509f90ab01863aacfbc0ba4:c780f4dee6e9', 'enc:v1:e62995f22d3fdd11d841ab65:f7880d455b4a4f7f386f645d6516854d:44ed41c32935bbefa65e', NULL, 'received', 'Cán bộ đánh dấu tin rác', NULL, NULL, NULL, NULL, 0, NULL, 'd96db4c365622dc725597bf05f267492', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', '2026-08-22 14:38:59', '2026-08-24 12:43:14', 'a79513112623560c7337887ac54675d82dedb51902fd4a6ad1c80ce95fa6c04b', '2026-09-06 14:38:59', 10, 1, 0, NULL, NULL, 'urgent', 'thuong', NULL, NULL, 0, NULL, NULL, '$2b$10$7Hdi5uoEj9vpXy42VNwo1OA8pPIsA8higyVPGtqTTsxilTqE0R.vC', '25ca2ec1-956f-4e57-b70d-2e263ea23eef', 1),
