SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------- Bảng: banned_words ----------
DROP TABLE IF EXISTS `banned_words`;
CREATE TABLE "banned_words" (
  "id" int NOT NULL AUTO_INCREMENT,
  "word" varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "word_type" enum('phrase','token') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'phrase',
  "is_active" tinyint(1) DEFAULT '1',
  "added_by" int DEFAULT NULL,
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE KEY "word" ("word"),
  KEY "added_by" ("added_by"),
  KEY "idx_word_type" ("word_type","is_active"),
  CONSTRAINT "banned_words_ibfk_1" FOREIGN KEY ("added_by") REFERENCES "staff" ("id") ON DELETE SET NULL
);


-- ---------- Bảng: blacklists ----------
DROP TABLE IF EXISTS `blacklists`;
CREATE TABLE "blacklists" (
  "id" int NOT NULL AUTO_INCREMENT,
  "identifier" varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  "kind" enum('device','ip') COLLATE utf8mb4_unicode_ci NOT NULL,
  "reason" varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "created_by" int DEFAULT NULL,
  "created_at" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "expires_at" datetime NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE KEY "uq_dinh_danh" ("identifier","kind"),
  KEY "idx_con_hieu_luc" ("kind","identifier","expires_at"),
  KEY "fk_bl_staff" ("created_by"),
  CONSTRAINT "fk_bl_staff" FOREIGN KEY ("created_by") REFERENCES "staff" ("id") ON DELETE SET NULL
);


-- ---------- Bảng: categories ----------
DROP TABLE IF EXISTS `categories`;
CREATE TABLE "categories" (
  "id" int NOT NULL AUTO_INCREMENT,
  "code" varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "name" varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "description" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "display_order" int DEFAULT '0',
  "is_active" tinyint(1) DEFAULT '1',
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  "updated_at" datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  "sla_days" int NOT NULL DEFAULT '15' COMMENT 'Số ngày phải giải quyết theo quy định',
  PRIMARY KEY ("id"),
  UNIQUE KEY "code" ("code")
);


-- ---------- Bảng: data_deletion_requests ----------
DROP TABLE IF EXISTS `data_deletion_requests`;
CREATE TABLE "data_deletion_requests" (
  "id" int NOT NULL AUTO_INCREMENT,
  "submission_id" bigint unsigned NOT NULL,
  "tracking_code" char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "status" enum('pending','done','rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  "requested_at" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "handled_at" datetime DEFAULT NULL,
  "handled_by" int DEFAULT NULL,
  "reason" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "requester_ip" varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY ("id"),
  KEY "idx_submission" ("submission_id"),
  KEY "idx_status" ("status","requested_at"),
  KEY "idx_tracking" ("tracking_code")
);


-- ---------- Bảng: incident_groups ----------
DROP TABLE IF EXISTS `incident_groups`;
CREATE TABLE "incident_groups" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "ward_id" int DEFAULT NULL,
  "category_id" int DEFAULT NULL,
  "first_submission_id" bigint NOT NULL,
  "submission_count" int NOT NULL DEFAULT '1',
  "first_reported_at" datetime NOT NULL,
  "last_reported_at" datetime NOT NULL,
  "acknowledged" tinyint(1) NOT NULL DEFAULT '0',
  "acknowledged_by" int DEFAULT NULL,
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  KEY "category_id" ("category_id"),
  KEY "acknowledged_by" ("acknowledged_by"),
  KEY "idx_ward_cat" ("ward_id","category_id"),
  KEY "idx_ack" ("acknowledged","last_reported_at"),
  CONSTRAINT "incident_groups_ibfk_1" FOREIGN KEY ("ward_id") REFERENCES "wards" ("id") ON DELETE SET NULL,
  CONSTRAINT "incident_groups_ibfk_2" FOREIGN KEY ("category_id") REFERENCES "categories" ("id") ON DELETE SET NULL,
  CONSTRAINT "incident_groups_ibfk_3" FOREIGN KEY ("acknowledged_by") REFERENCES "staff" ("id") ON DELETE SET NULL
);


-- ---------- Bảng: news ----------
DROP TABLE IF EXISTS `news`;
CREATE TABLE "news" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "title" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "summary" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "content" longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "category" enum('security','warning','guide','document') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "image_url" varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "source_name" varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "source_url" varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "is_external" tinyint(1) DEFAULT '1',
  "is_published" tinyint(1) DEFAULT '1',
  "view_count" int NOT NULL DEFAULT '0' COMMENT 'Số lượt xem, phục vụ khu Bà con đang quan tâm',
  "published_at" date DEFAULT NULL,
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  "updated_at" datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  "is_featured" tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = tin nổi bật, hiện to ở đầu trang',
  PRIMARY KEY ("id"),
  KEY "idx_category" ("category"),
  KEY "idx_published_at" ("published_at"),
  KEY "idx_is_published" ("is_published"),
  KEY "idx_noi_bat" ("is_featured","published_at"),
  KEY "idx_news_views" ("view_count")
);


-- ---------- Bảng: otp_codes ----------
DROP TABLE IF EXISTS `otp_codes`;
CREATE TABLE "otp_codes" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "email_hash" char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA-256 của email',
  "code_hash" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Mã OTP đã băm bcrypt',
  "attempts" int DEFAULT '0' COMMENT 'Nhập sai quá 5 lần thì huỷ mã',
  "is_used" tinyint(1) DEFAULT '0',
  "expires_at" datetime NOT NULL COMMENT 'Hết hạn sau 10 phút',
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  "ip_address" varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY ("id"),
  KEY "idx_email_hash" ("email_hash","is_used","expires_at"),
  KEY "idx_expires" ("expires_at")
);


-- ---------- Bảng: qr_points ----------
DROP TABLE IF EXISTS `qr_points`;
CREATE TABLE "qr_points" (
  "id" int NOT NULL AUTO_INCREMENT,
  "code" char(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  "name" varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  "ward_id" int NOT NULL,
  "note" varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "is_active" tinyint(1) NOT NULL DEFAULT '1',
  "created_by" int DEFAULT NULL,
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE KEY "code" ("code"),
  KEY "created_by" ("created_by"),
  KEY "idx_code" ("code"),
  KEY "idx_ward" ("ward_id"),
  CONSTRAINT "qr_points_ibfk_1" FOREIGN KEY ("ward_id") REFERENCES "wards" ("id") ON DELETE CASCADE,
  CONSTRAINT "qr_points_ibfk_2" FOREIGN KEY ("created_by") REFERENCES "staff" ("id") ON DELETE SET NULL
);


-- ---------- Bảng: refresh_tokens ----------
DROP TABLE IF EXISTS `refresh_tokens`;
CREATE TABLE "refresh_tokens" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "staff_id" int NOT NULL,
  "token_hash" char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA-256 của refresh token (không lưu token thô)',
  "revoked" tinyint(1) DEFAULT '0',
  "expires_at" datetime NOT NULL,
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE KEY "token_hash" ("token_hash"),
  KEY "idx_token_hash" ("token_hash"),
  KEY "idx_staff" ("staff_id"),
  CONSTRAINT "refresh_tokens_ibfk_1" FOREIGN KEY ("staff_id") REFERENCES "staff" ("id") ON DELETE CASCADE
);


-- ---------- Bảng: report_messages ----------
DROP TABLE IF EXISTS `report_messages`;
CREATE TABLE "report_messages" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "submission_id" bigint NOT NULL,
  "sender_type" enum('staff','reporter') COLLATE utf8mb4_unicode_ci NOT NULL,
  "staff_id" int DEFAULT NULL,
  "message" text COLLATE utf8mb4_unicode_ci NOT NULL,
  "created_at" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "read_by_staff" tinyint(1) NOT NULL DEFAULT '0',
  "read_by_reporter" tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY ("id"),
  KEY "idx_submission" ("submission_id","created_at"),
  KEY "idx_chua_doc" ("submission_id","read_by_staff"),
  KEY "fk_msg_staff" ("staff_id"),
  CONSTRAINT "fk_msg_staff" FOREIGN KEY ("staff_id") REFERENCES "staff" ("id") ON DELETE SET NULL,
  CONSTRAINT "fk_msg_submission" FOREIGN KEY ("submission_id") REFERENCES "submissions" ("id") ON DELETE CASCADE
);


-- ---------- Bảng: staff ----------
DROP TABLE IF EXISTS `staff`;
CREATE TABLE "staff" (
  "id" int NOT NULL AUTO_INCREMENT,
  "full_name" varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "username" varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "password_hash" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "email" varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "phone" varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "role" enum('admin','manager','handler') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'handler',
  "assigned_category_id" int DEFAULT NULL,
  "is_active" tinyint(1) DEFAULT '1',
  "last_login" datetime DEFAULT NULL,
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  "updated_at" datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  "failed_attempts" int NOT NULL DEFAULT '0',
  "locked_until" datetime DEFAULT NULL,
  "sessions_valid_from" datetime DEFAULT NULL,
  PRIMARY KEY ("id"),
  UNIQUE KEY "username" ("username"),
  KEY "assigned_category_id" ("assigned_category_id"),
  KEY "idx_username" ("username"),
  KEY "idx_role" ("role"),
  CONSTRAINT "staff_ibfk_1" FOREIGN KEY ("assigned_category_id") REFERENCES "categories" ("id") ON DELETE SET NULL
);


-- ---------- Bảng: staff_activity_logs ----------
DROP TABLE IF EXISTS `staff_activity_logs`;
CREATE TABLE "staff_activity_logs" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "staff_id" int DEFAULT NULL,
  "action" varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "target_type" varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "target_id" bigint DEFAULT NULL,
  "details" json DEFAULT NULL,
  "ip_address" varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  "attempted_username" varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY ("id"),
  KEY "idx_staff" ("staff_id"),
  KEY "idx_action" ("action"),
  KEY "idx_created_at" ("created_at"),
  CONSTRAINT "staff_activity_logs_ibfk_1" FOREIGN KEY ("staff_id") REFERENCES "staff" ("id") ON DELETE CASCADE
);


-- ---------- Bảng: status_history ----------
DROP TABLE IF EXISTS `status_history`;
CREATE TABLE "status_history" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "submission_id" bigint NOT NULL,
  "old_status" enum('pending_review','received','processing','resolved','rejected','spam') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "new_status" enum('pending_review','received','processing','resolved','rejected','spam') COLLATE utf8mb4_unicode_ci NOT NULL,
  "note" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "changed_by" int DEFAULT NULL,
  "changed_at" datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  KEY "changed_by" ("changed_by"),
  KEY "idx_submission" ("submission_id"),
  KEY "idx_changed_at" ("changed_at"),
  CONSTRAINT "status_history_ibfk_1" FOREIGN KEY ("submission_id") REFERENCES "submissions" ("id") ON DELETE CASCADE,
  CONSTRAINT "status_history_ibfk_2" FOREIGN KEY ("changed_by") REFERENCES "staff" ("id") ON DELETE SET NULL
);


-- ---------- Bảng: submission_images ----------
DROP TABLE IF EXISTS `submission_images`;
CREATE TABLE "submission_images" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "submission_id" bigint NOT NULL,
  "image_url" longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ảnh base64 (data URL) - phải LONGTEXT vì rất dài',
  "original_name" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "file_size" int DEFAULT NULL,
  "mime_type" varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "is_verified" tinyint(1) DEFAULT '0',
  "moderation_status" enum('safe','suspicious','blocked') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'safe',
  "uploaded_at" datetime DEFAULT CURRENT_TIMESTAMP,
  "cloudinary_id" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ID ảnh trên Cloudinary — dùng để xoá ảnh khi cần',
  "storage" enum('base64','cloudinary') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'base64' COMMENT 'Ảnh đang lưu ở đâu',
  PRIMARY KEY ("id"),
  KEY "idx_submission" ("submission_id"),
  CONSTRAINT "submission_images_ibfk_1" FOREIGN KEY ("submission_id") REFERENCES "submissions" ("id") ON DELETE CASCADE
);


-- ---------- Bảng: submissions ----------
DROP TABLE IF EXISTS `submissions`;
CREATE TABLE "submissions" (
  "id" bigint NOT NULL AUTO_INCREMENT,
  "tracking_code" char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "original_content" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "ai_processed_content" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "ai_confidence" decimal(4,3) DEFAULT NULL,
  "ai_keywords" json DEFAULT NULL,
  "content_hash" char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "category_id" int DEFAULT NULL,
  "ai_suggested_category_id" int DEFAULT NULL,
  "sender_name" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "sender_phone" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "sender_email" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Đã mã hoá AES-256-GCM',
  "status" enum('pending_review','received','processing','resolved','rejected','spam') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'received',
  "rejection_reason" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "assigned_to" int DEFAULT NULL,
  "resolution_note" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "resolved_by" int DEFAULT NULL,
  "resolved_at" datetime DEFAULT NULL,
  "is_flagged" tinyint(1) DEFAULT '0',
  "flag_reason" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "ip_address" varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "user_agent" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "created_at" datetime DEFAULT CURRENT_TIMESTAMP,
  "updated_at" datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  "sender_phone_hash" char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SHA-256 của SĐT — dùng dò spam, không lộ số thật',
  "deadline_at" datetime DEFAULT NULL COMMENT 'Hạn phải giải quyết',
  "ward_id" int DEFAULT NULL,
  "is_verified_otp" tinyint(1) DEFAULT '0' COMMENT 'Người gửi đã xác thực email qua OTP',
  "is_anonymous" tinyint(1) DEFAULT '0' COMMENT 'TRUE = người gửi chọn ẩn danh, không cung cấp danh tính',
  "reviewed_by" int DEFAULT NULL COMMENT 'Cán bộ đã duyệt ý kiến ẩn danh',
  "reviewed_at" datetime DEFAULT NULL,
  "urgency" enum('normal','important','urgent') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal' COMMENT 'Mức khẩn cấp do người dân tự chọn',
  "security_level" enum('thuong','can_bao_ve','mat') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'thuong' COMMENT 'Cấp độ bảo mật: thuong/can_bao_ve/mat',
  "deleted_at" datetime DEFAULT NULL COMMENT 'Thời điểm đưa vào thùng rác; tự xoá hẳn sau 7 ngày',
  "deleted_by" int DEFAULT NULL COMMENT 'ID cán bộ đã đưa vào thùng rác',
  "identity_erased" tinyint(1) NOT NULL DEFAULT '0' COMMENT 'TRUE = danh tính đã được xoá theo yêu cầu của người dân',
  "identity_erased_at" datetime DEFAULT NULL COMMENT 'Thời điểm xoá danh tính',
  "incident_group_id" bigint DEFAULT NULL,
  "chat_pin_hash" varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Băm bcrypt của mã PIN vào phòng chat',
  "device_id" varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Mã thiết bị do trình duyệt sinh, dùng chặn spam',
  "is_spam" tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = bị chặn ngầm, không hiện cho cán bộ',
  PRIMARY KEY ("id"),
  UNIQUE KEY "tracking_code" ("tracking_code"),
  KEY "ai_suggested_category_id" ("ai_suggested_category_id"),
  KEY "resolved_by" ("resolved_by"),
  KEY "idx_tracking_code" ("tracking_code"),
  KEY "idx_status" ("status"),
  KEY "idx_category" ("category_id"),
  KEY "idx_created_at" ("created_at"),
  KEY "idx_content_hash" ("content_hash"),
  KEY "idx_ip_created" ("ip_address","created_at"),
  KEY "idx_phone_created" ("sender_phone","created_at"),
  KEY "idx_phone_hash" ("sender_phone_hash","created_at"),
  KEY "idx_deadline" ("deadline_at","status"),
  KEY "idx_ward" ("ward_id"),
  KEY "idx_assigned" ("assigned_to","status"),
  KEY "fk_submission_reviewer" ("reviewed_by"),
  KEY "idx_pending" ("status","is_anonymous","created_at"),
  KEY "idx_urgency" ("urgency","status"),
  KEY "idx_deleted_at" ("deleted_at"),
  KEY "idx_incident_group" ("incident_group_id"),
  KEY "idx_ward_cat_time" ("ward_id","category_id","created_at"),
  KEY "idx_spam_ip" ("ip_address","is_spam","created_at"),
  KEY "idx_submissions_security_level" ("security_level"),
  CONSTRAINT "fk_submission_incident_group" FOREIGN KEY ("incident_group_id") REFERENCES "incident_groups" ("id") ON DELETE SET NULL,
  CONSTRAINT "fk_submission_reviewer" FOREIGN KEY ("reviewed_by") REFERENCES "staff" ("id") ON DELETE SET NULL,
  CONSTRAINT "fk_submission_ward" FOREIGN KEY ("ward_id") REFERENCES "wards" ("id") ON DELETE SET NULL,
  CONSTRAINT "fk_submissions_incident_group" FOREIGN KEY ("incident_group_id") REFERENCES "incident_groups" ("id") ON DELETE SET NULL,
  CONSTRAINT "submissions_ibfk_1" FOREIGN KEY ("category_id") REFERENCES "categories" ("id") ON DELETE SET NULL,
  CONSTRAINT "submissions_ibfk_2" FOREIGN KEY ("ai_suggested_category_id") REFERENCES "categories" ("id") ON DELETE SET NULL,
  CONSTRAINT "submissions_ibfk_3" FOREIGN KEY ("assigned_to") REFERENCES "staff" ("id") ON DELETE SET NULL,
  CONSTRAINT "submissions_ibfk_4" FOREIGN KEY ("resolved_by") REFERENCES "staff" ("id") ON DELETE SET NULL
);


-- ---------- Bảng: system_settings ----------
DROP TABLE IF EXISTS `system_settings`;
CREATE TABLE "system_settings" (
  "id" int NOT NULL AUTO_INCREMENT,
  "key" varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "value" text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  "description" varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  "updated_at" datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE KEY "key" ("key")
);


-- ---------- Bảng: wards ----------
DROP TABLE IF EXISTS `wards`;
CREATE TABLE "wards" (
  "id" int NOT NULL AUTO_INCREMENT,
  "name" varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  "lat" decimal(10,7) NOT NULL,
  "lng" decimal(10,7) NOT NULL,
  "display_order" int DEFAULT '0',
  PRIMARY KEY ("id"),
  UNIQUE KEY "name" ("name")
);


-- ========== VIEW ==========
DROP VIEW IF EXISTS `vw_blacklist_active`;
CREATE VIEW "vw_blacklist_active" AS select "b"."id" AS "id","b"."identifier" AS "identifier","b"."kind" AS "kind","b"."reason" AS "reason","b"."created_at" AS "created_at","b"."expires_at" AS "expires_at","st"."full_name" AS "nguoi_khoa",timestampdiff(MINUTE,now(),"b"."expires_at") AS "con_lai_phut" from ("blacklists" "b" left join "staff" "st" on(("st"."id" = "b"."created_by"))) where ("b"."expires_at" > now()) order by "b"."created_at" desc;

DROP VIEW IF EXISTS `vw_category_stats`;
CREATE VIEW "vw_category_stats" AS select "c"."id" AS "id","c"."code" AS "code","c"."name" AS "name",count("s"."id") AS "total_count",sum((case when ("s"."status" = 'received') then 1 else 0 end)) AS "received_count",sum((case when ("s"."status" = 'processing') then 1 else 0 end)) AS "processing_count",sum((case when ("s"."status" = 'resolved') then 1 else 0 end)) AS "resolved_count",sum((case when ("s"."status" = 'rejected') then 1 else 0 end)) AS "rejected_count" from ("categories" "c" left join "submissions" "s" on(("c"."id" = "s"."category_id"))) group by "c"."id","c"."code","c"."name";

DROP VIEW IF EXISTS `vw_chat_chua_doc`;
CREATE VIEW "vw_chat_chua_doc" AS select "m"."submission_id" AS "submission_id",count(0) AS "so_tin_chua_doc",max("m"."created_at") AS "tin_moi_nhat" from "report_messages" "m" where (("m"."sender_type" = 'reporter') and ("m"."read_by_staff" = 0)) group by "m"."submission_id";

DROP VIEW IF EXISTS `vw_dashboard_stats`;
CREATE VIEW "vw_dashboard_stats" AS select (select count(0) from "submissions") AS "total_submissions",(select count(0) from "submissions" where ("submissions"."status" = 'received')) AS "pending_count",(select count(0) from "submissions" where ("submissions"."status" = 'processing')) AS "processing_count",(select count(0) from "submissions" where ("submissions"."status" = 'resolved')) AS "resolved_count",(select count(0) from "submissions" where ("submissions"."status" = 'rejected')) AS "rejected_count",(select count(0) from "submissions" where ("submissions"."is_flagged" = true)) AS "flagged_count",(select count(0) from "submissions" where (cast("submissions"."created_at" as date) = curdate())) AS "today_count",(select count(0) from "staff" where ("staff"."is_active" = true)) AS "active_staff_count";

DROP VIEW IF EXISTS `vw_deletion_pending`;
CREATE VIEW "vw_deletion_pending" AS select "d"."id" AS "id","d"."tracking_code" AS "tracking_code","d"."requested_at" AS "requested_at",(to_days(now()) - to_days("d"."requested_at")) AS "so_ngay_cho","s"."status" AS "trang_thai_ho_so","c"."name" AS "nhom_xu_ly","s"."deadline_at" AS "han_xu_ly" from (("data_deletion_requests" "d" join "submissions" "s" on(("s"."id" = "d"."submission_id"))) left join "categories" "c" on(("c"."id" = "s"."category_id"))) where ("d"."status" = 'pending');

DROP VIEW IF EXISTS `vw_login_canh_bao`;
CREATE VIEW "vw_login_canh_bao" AS select "staff_activity_logs"."ip_address" AS "dia_chi_ip",count(0) AS "so_lan_that_bai",count(distinct "staff_activity_logs"."attempted_username") AS "so_tai_khoan_bi_thu",min("staff_activity_logs"."created_at") AS "lan_dau",max("staff_activity_logs"."created_at") AS "lan_cuoi" from "staff_activity_logs" where (("staff_activity_logs"."action" = 'login_failed') and ("staff_activity_logs"."created_at" > (now() - interval 24 hour))) group by "staff_activity_logs"."ip_address" having (count(0) >= 5);

DROP VIEW IF EXISTS `vw_resolution_performance`;
CREATE VIEW "vw_resolution_performance" AS select "c"."name" AS "category_name",count("s"."id") AS "resolved_total",round(avg(timestampdiff(HOUR,"s"."created_at","s"."resolved_at")),1) AS "avg_resolve_hours",max(timestampdiff(HOUR,"s"."created_at","s"."resolved_at")) AS "max_resolve_hours" from ("submissions" "s" join "categories" "c" on(("c"."id" = "s"."category_id"))) where (("s"."status" = 'resolved') and ("s"."resolved_at" is not null)) group by "c"."id","c"."name";

DROP VIEW IF EXISTS `vw_review_queue`;
CREATE VIEW "vw_review_queue" AS select count(0) AS "pending_count",sum(("submissions"."created_at" < (now() - interval 24 hour))) AS "pending_over_24h" from "submissions" where ("submissions"."status" = 'pending_review');

DROP VIEW IF EXISTS `vw_sla_stats`;
CREATE VIEW "vw_sla_stats" AS select (select count(0) from "submissions" where (("submissions"."status" in ('received','processing')) and ("submissions"."deadline_at" is not null) and ("submissions"."deadline_at" < now()))) AS "overdue_count",(select count(0) from "submissions" where (("submissions"."status" in ('received','processing')) and ("submissions"."deadline_at" is not null) and ("submissions"."deadline_at" >= now()) and ("submissions"."deadline_at" < (now() + interval 3 day)))) AS "near_due_count",(select count(0) from "submissions" where (("submissions"."status" in ('received','processing')) and ("submissions"."assigned_to" is null))) AS "unassigned_count",(select count(0) from "submissions" where ("submissions"."status" = 'pending_review')) AS "pending_review_count";

DROP VIEW IF EXISTS `vw_trash`;
CREATE VIEW "vw_trash" AS select "s"."id" AS "id","s"."tracking_code" AS "tracking_code","s"."original_content" AS "original_content","s"."ai_processed_content" AS "ai_processed_content","s"."status" AS "status","s"."is_anonymous" AS "is_anonymous","s"."created_at" AS "created_at","s"."deleted_at" AS "deleted_at","s"."deleted_by" AS "deleted_by","st"."full_name" AS "deleted_by_name","c"."name" AS "category_name","c"."code" AS "category_code",(to_days(("s"."deleted_at" + interval 7 day)) - to_days(now())) AS "days_left" from (("submissions" "s" left join "staff" "st" on(("st"."id" = "s"."deleted_by"))) left join "categories" "c" on(("c"."id" = "s"."category_id"))) where ("s"."deleted_at" is not null) order by "s"."deleted_at" desc;

-- ========== THỦ TỤC VÀ HÀM ==========
DELIMITER $$
DROP PROCEDURE IF EXISTS `check_spam`$$
CREATE DEFINER="avnadmin"@"%" PROCEDURE "check_spam"(IN p_ip VARCHAR(45), IN p_phone VARCHAR(20), IN p_content_hash CHAR(64))
BEGIN
    SELECT COUNT(*) AS submissions_last_hour,
           MAX(created_at) AS last_submission_at,
           TIMESTAMPDIFF(SECOND, MAX(created_at), NOW()) AS seconds_since_last,
           EXISTS(SELECT 1 FROM submissions
                  WHERE content_hash = p_content_hash AND created_at > NOW() - INTERVAL 1 HOUR) AS is_duplicate_content
    FROM submissions
    WHERE (ip_address = p_ip OR sender_phone = p_phone) AND created_at > NOW() - INTERVAL 1 HOUR;
END$$

DROP FUNCTION IF EXISTS `generate_tracking_code`$$
CREATE DEFINER="avnadmin"@"%" FUNCTION "generate_tracking_code"() RETURNS char(6) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci
    READS SQL DATA
BEGIN
    DECLARE charset VARCHAR(31) DEFAULT 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
    DECLARE code CHAR(6);
    DECLARE i INT;
    DECLARE dup INT DEFAULT 1;
    WHILE dup > 0 DO
        SET code = '';
        SET i = 0;
        WHILE i < 6 DO
            SET code = CONCAT(code, SUBSTRING(charset, FLOOR(1 + RAND() * 31), 1));
            SET i = i + 1;
        END WHILE;
        SELECT COUNT(*) INTO dup FROM submissions WHERE tracking_code = code;
    END WHILE;
    RETURN code;
END$$

DROP PROCEDURE IF EXISTS `get_submission_by_tracking`$$
CREATE DEFINER="avnadmin"@"%" PROCEDURE "get_submission_by_tracking"(IN p_tracking_code CHAR(6))
BEGIN
    SELECT s.id, s.tracking_code, s.original_content, s.ai_processed_content,
           c.code AS category_code, c.name AS category_name,
           s.status, s.rejection_reason, s.resolution_note, s.created_at, s.updated_at,
           TIMESTAMPDIFF(HOUR, s.created_at, NOW()) AS hours_since_submitted
    FROM submissions s LEFT JOIN categories c ON s.category_id = c.id
    WHERE s.tracking_code = UPPER(p_tracking_code);
    SELECT h.old_status, h.new_status, h.note, h.changed_at
    FROM status_history h JOIN submissions s ON s.id = h.submission_id
    WHERE s.tracking_code = UPPER(p_tracking_code) ORDER BY h.changed_at ASC;
    SELECT i.image_url, i.mime_type, i.moderation_status, i.uploaded_at
    FROM submission_images i JOIN submissions s ON s.id = i.submission_id
    WHERE s.tracking_code = UPPER(p_tracking_code) AND i.moderation_status <> 'blocked';
END$$

DROP PROCEDURE IF EXISTS `update_submission_status`$$
CREATE DEFINER="avnadmin"@"%" PROCEDURE "update_submission_status"(
    IN p_submission_id BIGINT,
    IN p_new_status ENUM('received','processing','resolved','rejected'),
    IN p_note TEXT,
    IN p_rejection_reason TEXT,
    IN p_staff_id INT
)
BEGIN
    DECLARE v_old_status ENUM('received','processing','resolved','rejected');
    SELECT status INTO v_old_status FROM submissions WHERE id = p_submission_id;
    UPDATE submissions
    SET status = p_new_status,
        rejection_reason = CASE WHEN p_new_status = 'rejected' THEN p_rejection_reason ELSE rejection_reason END,
        resolved_by = CASE WHEN p_new_status IN ('resolved','rejected') THEN p_staff_id ELSE resolved_by END,
        resolved_at = CASE WHEN p_new_status IN ('resolved','rejected') THEN NOW() ELSE resolved_at END,
        updated_at = NOW()
    WHERE id = p_submission_id;
    VALUES (p_submission_id, v_old_status, p_new_status,
            CASE WHEN p_new_status = 'rejected' THEN COALESCE(p_rejection_reason, p_note) ELSE p_note END,
            p_staff_id);
    VALUES (p_staff_id, 'update_status', 'submission', p_submission_id,
            JSON_OBJECT('old_status', v_old_status, 'new_status', p_new_status));
END$$

DELIMITER ;

-- ========== TRIGGER ==========
DELIMITER $$
DROP TRIGGER IF EXISTS `trg_submission_received`$$
CREATE DEFINER="avnadmin"@"%" TRIGGER "trg_submission_received" AFTER INSERT ON "submissions" FOR EACH ROW BEGIN
    VALUES (NEW.id, NULL, 'received', 'Hệ thống đã ghi nhận ý kiến và cấp mã tra cứu.');
END$$

DELIMITER ;

SET FOREIGN_KEY_CHECKS = 1;
